import{_ as o,c as t,o as a,ag as r}from"./chunks/framework.dvv-DFtf.js";const p=JSON.parse('{"title":"Actions","description":"","frontmatter":{},"headers":[],"relativePath":"features/actions.md","filePath":"features/actions.md"}'),i={name:"features/actions.md"};function l(s,e,n,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h1><p>Kubby provides quick actions for common Kubernetes operations, accessible via keyboard shortcuts or the action bar.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Actions let you perform operations on resources without writing kubectl commands. Each action is designed to be fast, safe, and provide clear feedback.</p><h2 id="available-actions" tabindex="-1">Available Actions <a class="header-anchor" href="#available-actions" aria-label="Permalink to &quot;Available Actions&quot;">​</a></h2><h3 id="scale" tabindex="-1">Scale <a class="header-anchor" href="#scale" aria-label="Permalink to &quot;Scale&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>S</code> (on Deployments)</p><p>Adjust the number of replicas for a deployment:</p><ol><li>Press <code>S</code> on a deployment</li><li>Enter the desired replica count</li><li>Confirm to apply</li></ol><p>The scale dialog shows:</p><ul><li>Current replica count</li><li>HorizontalPodScalers, PodDisruptionBudgets if found</li><li>Input for new replica count as well for related resources</li></ul><h3 id="rolling-restart" tabindex="-1">Rolling Restart <a class="header-anchor" href="#rolling-restart" aria-label="Permalink to &quot;Rolling Restart&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>R</code> (on Deployments)</p><p>Perform a rolling restart of all pods in a deployment:</p><ol><li>Press <code>R</code> on a deployment</li><li>Review the confirmation and information: <ol><li>related HorizontalPodScaler and PodDisruptionBudget if found</li><li>current status summary</li></ol></li><li>Confirm to initiate restart</li></ol><h3 id="edit" tabindex="-1">Edit <a class="header-anchor" href="#edit" aria-label="Permalink to &quot;Edit&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>E</code></p><p>Edit any resource&#39;s YAML definition:</p><ol><li>Press <code>E</code> on a resource</li><li>Your configured editor opens with the resource YAML</li><li>Make changes and save</li><li>Close the editor to apply changes</li></ol><div class="tip custom-block"><p class="custom-block-title">Editor Configuration</p><p>Kubby uses your system&#39;s default editor. Set the <code>KUBE_EDITOR</code> or <code>EDITOR</code> environment variable to customize.</p></div><h3 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>Del</code></p><p>Delete a resource from the cluster:</p><ol><li>Press <code>Del</code> on a resource</li><li>Review the confirmation dialog</li><li>Confirm deletion</li></ol><div class="warning custom-block"><p class="custom-block-title">Destructive Action</p><p>Deletion is permanent. Always verify you&#39;re deleting the correct resource.</p></div><h3 id="describe" tabindex="-1">Describe <a class="header-anchor" href="#describe" aria-label="Permalink to &quot;Describe&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>D</code></p><p>View detailed information about a resource:</p><ol><li>Press <code>D</code> on any resource</li><li>Opens the Resource Detail view</li><li>Shows full resource specification and status</li></ol><h3 id="view-logs" tabindex="-1">View Logs <a class="header-anchor" href="#view-logs" aria-label="Permalink to &quot;View Logs&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>L</code></p><p>Stream logs from pods or containers:</p><ol><li>Press <code>L</code> on a pod, deployment, or container</li><li>Opens the Log Viewer</li><li>Logs stream in real-time</li></ol><h3 id="port-forward" tabindex="-1">Port Forward <a class="header-anchor" href="#port-forward" aria-label="Permalink to &quot;Port Forward&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>F</code></p><p>Create a tunnel to access pods or services locally:</p><ol><li>Press <code>F</code> on a pod, container, or service</li><li>Select the port to forward</li><li>Enter a local port (or accept the default)</li><li>Confirm to start the forward</li></ol><p>Press <code>F</code> again to see opened ports and remove them.</p><h1 id="shell-access" tabindex="-1">Shell Access <a class="header-anchor" href="#shell-access" aria-label="Permalink to &quot;Shell Access&quot;">​</a></h1><p>Shell Access lets you open interactive terminal sessions directly into containers running in your cluster.</p><p>Access Shell by pressing <code>S</code> on a pod or container. This opens an external terminal with a session inside the container, equivalent to <code>kubectl exec -it</code>.</p><div class="tip custom-block"><p class="custom-block-title">Minimal Images</p><p>Many production containers use minimal base images without debugging tools. Consider using <a href="https://kubernetes.io/docs/tasks/debug/debug-application/debug-running-pod/#ephemeral-container" target="_blank" rel="noreferrer">ephemeral debug containers</a> for advanced debugging. Kubby supports custom run command you can use them to launch any image, see <a href="/configuration.html#custom-run-commands">Custom Run Commands</a> in configuration for more details.</p></div><h3 id="jump" tabindex="-1">Jump <a class="header-anchor" href="#jump" aria-label="Permalink to &quot;Jump&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>J</code></p><p>Navigate to related resources:</p><ol><li>Press <code>J</code> on a resource with related items</li><li>Select from the dropdown (e.g., Pods for a Deployment)</li><li>View opens filtered to related resources</li></ol><h3 id="run-custom-command" tabindex="-1">Run Custom Command <a class="header-anchor" href="#run-custom-command" aria-label="Permalink to &quot;Run Custom Command&quot;">​</a></h3><p><strong>Shortcut:</strong> <code>U</code> (when available)</p><p>Execute custom commands defined for specific resource types:</p><ol><li>Press <code>U</code> on a resource with custom commands</li><li>Select from available commands</li><li>Command executes against the resource</li></ol><p>The custom commands can be configured in <a href="/configuration.html">Kubby config</a>.</p><h3 id="ai-agent" tabindex="-1">AI Agent <a class="header-anchor" href="#ai-agent" aria-label="Permalink to &quot;AI Agent&quot;">​</a></h3><p>See <a href="/features/ai-assistant.html">AI Assistant Command</a>.</p><h2 id="action-bar" tabindex="-1">Action Bar <a class="header-anchor" href="#action-bar" aria-label="Permalink to &quot;Action Bar&quot;">​</a></h2><p>The action bar at the bottom of the screen shows available actions for the currently selected resource. Actions vary by resource type:</p><table tabindex="0"><thead><tr><th>Resource</th><th>Available Actions</th></tr></thead><tbody><tr><td>Deployment</td><td>Pods, Describe, Edit, Jump, Logs, Rolling Restart, Scale, Delete</td></tr><tr><td>Pod</td><td>Containers, Describe, Edit, Jump, Logs, Port-Forward, Shell, Delete</td></tr><tr><td>Service</td><td>Pods, Describe, Edit, Jump, Port-Forward, Delete</td></tr><tr><td>ConfigMap</td><td>Describe, Edit, Jump, Delete</td></tr><tr><td>Secret</td><td>Describe, Edit, Jump, Delete</td></tr><tr><td>Other</td><td>Describe, Delete</td></tr></tbody></table><h2 id="safety-features" tabindex="-1">Safety Features <a class="header-anchor" href="#safety-features" aria-label="Permalink to &quot;Safety Features&quot;">​</a></h2><h3 id="confirmation-dialogs" tabindex="-1">Confirmation Dialogs <a class="header-anchor" href="#confirmation-dialogs" aria-label="Permalink to &quot;Confirmation Dialogs&quot;">​</a></h3><p>Destructive actions require confirmation.</p><h3 id="read-only-mode" tabindex="-1">Read-Only Mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to &quot;Read-Only Mode&quot;">​</a></h3><p>Usefully for when connected to production or sensitive clusters:</p><ul><li>Modifying actions can be disabled</li><li>Visual indicators show read-only state</li><li>Prevents accidental changes</li></ul><p>Can be configured in <a href="/configuration.html">Kubby config</a>.</p>',63)])])}const m=o(i,[["render",l]]);export{p as __pageData,m as default};
